tracked=subprocess.check_output(['git','ls-files','-z']).decode().split('\0')
changed=[]
for name in filter(None,tracked):
 data=Path(name).read_bytes()
 if data != subprocess.check_output(['git','show','HEAD:'+name]): changed.append(name)
untracked=subprocess.check_output(['git','ls-files','--others','--exclude-standard','-z']).decode().split('\0')
actual=set(changed)|set(filter(None,untracked))
if actual != allowed: raise SystemExit(f'Unexpected final scope: {actual}')
for name in allowed:
 for i,line in enumerate(Path(name).read_text().splitlines(),1):
